// --- Internal Structures and Logic ---

/**
 * Deterministic Pseudo-Random Number Generator (based on Seed)
 * Ensures reproducibility required by the prompt.
 */
class PRNG {
    constructor(seed) {
        this.state = seed;
    }

    next() {
        this.state = (this.state * 9301 + 49297) % 233280;
        return this.state / 233280.0; // Return float [0, 1)
    }

    nextInt(max) {
        return Math.floor((this.next() * max));
    }
}


/** Represents a cell in the maze grid */
class Cell {
    constructor(r, c) {
        this.r = r;
        this.c = c;
        // Walls are true if they block passage (i.e., initially solid walls)
        this.walls = { north: true, east: true, south: true, west: true };
        this.visited = false; // Used during maze generation
    }

    setWall(direction, isBlocked) {
        this.walls[direction] = !!isBlocked;
    }

    // Helper to get opposite direction (N <-> S, W <-> E)
    getOpposite(dir) {
        if (dir === 'north') return 'south';
        if (dir === 'south') return 'north';
        if (dir === 'east') return 'west';
        if (dir === 'west') return 'east';
        return null;
    }
}

/** Represents a Bot Agent */
class Bot {
    constructor(id, initialSeed) {
        this.id = id;
        // Use the bot ID and agent index to create unique seeds/preferences
        this.rng = new PRNG(initialSeed); 

        // Core State
        this.path = [];          // [{r, c}, ...] Full history of visited cells
        this.deadEnds = new Set(); // Set<string> "r,c" keys for explored dead ends (simplified memory)

        // Movement State
        this.currentCell = null; 
        this.nextMove = null;    // For interpolation rendering

        this.finishTick = null;  // Null until arrival

        // Preferences: Define search order based on seed.
        // Directions: N, E, S, W
        this.preferredDirections = [];
        const directions = ['north', 'east', 'south', 'west'];
        for (let i = 0; i < directions.length; i++) {
            // Shuffle the direction order using the agent's unique RNG
            const j = Math.floor(this.rng.next() * (i + 1));
            [directions[i], directions[j]] = [directions[j], directions[i]];
        }
        this.preferredDirections = directions;

        // Initialize position and history
    }

    /** Sets the initial state for a bot upon game start. */
    initialize(r, c) {
        this.currentCell = { r: r, c: c };
        this.path = [{ r: r, c: c }];
        this.nextMove = null; // Starts at current cell
    }

    /** 
     * The core bot logic: attempts to move one step (DFS exploration). 
     * @param tickCount - Simulation tick count (unused internally but required signature)
     */
    move(tickCount) {
        if (this.finishTick !== null) return;

        const current = this.currentCell;
        let nextPosition = null;
        let moved = false;

        // 1. Check Preferred Neighbors (Exploration attempt)
        for (const direction of this.preferredDirections) {
            const [dr, dc] = this._getDelta(direction);
            const nr = current.r + dr;
            const nc = current.c + dc;

            // Boundary check and Wall Check using the global API
            if (nr >= 0 && nr < window.game.size.rows && 
                nc >= 0 && nc < window.game.size.cols) {

                const wallData = window.game.walls(current.r, current.c);
                let isPassageOpen = false;
                if (direction === 'north' && !wallData.n) isPassageOpen = true;
                else if (direction === 'east' && !wallData.e) isPassageOpen = true;
                else if (direction === 'south' && !wallData.s) isPassageOpen = true;
                else if (direction === 'west' && !wallData.w) isPassageOpen = true;

                // Check if the neighbor cell exists and has not been fully explored recently 
                // (Simplified check: prefer movement to unvisited/less-traversed cells)
                const targetCell = this.path.find(p => p.r === nr && p.c === nc);

                if (isPassageOpen) {
                    // Success! Found a path.
                    nextPosition = { r: nr, c: nc };
                    moved = true;
                    break; 
                }
            }
        }

        if (moved) {
            this._advance(nextPosition);
            return true;
        }


        // 2. Backtracking Logic (If no preferred forward moves were found)
        let backtracked = false;
        while (this.path.length > 1) {
            const lastStep = this.path[this.path.length - 1];
            const prevStep = this.path[this.path.length - 2];

            // Check if the connection between last and previous cell is a traversable passage
            // We simulate moving back from 'lastStep' to 'prevStep'.
            if (this._isPassageOpen(prevStep, lastStep, current)) { // Using current state for simplification check
                nextPosition = prevStep;
                moved = true;
                backtracked = true;
                break;
            } else {
                // If the passage was blocked or already marked as fully explored/dead end cycle, 
                // we must step back.
                this.currentCell = prevStep; // Update internal state for rendering purposes
                nextPosition = prevStep;
                moved = true;
                break;
            }
        }

        if (moved && nextPosition) {
             this._advance(nextPosition);
             return true;
        }


        // 3. Failure: Stuck at current location, must have finished or is truly blocked.
        return false;
    }

    /** Updates internal state after moving from 'from' to 'to'. */
    _advance(to) {
        this.currentCell = to;
        this.path.push({ r: to.r, c: to.c });
        this.nextMove = null; // Ready for next movement calculation
    }

    /** Checks if a passage between two cells (p1 -> p2) is open based on current global wall knowledge. */
    _isPassageOpen(p1, p2, from) {
        const dr = Math.abs(from.r - p2.r);
        const dc = Math.abs(from.c - p2.c);

        // Calculate direction of movement relative to 'from'
        if (dr === 1 && dc === 0) { // Vertical move
            return this._checkDirectionWall(from, p2.r > from.r ? 'south' : 'north');
        } else if (dr === 0 && dc === 1) { // Horizontal move
            return this._checkDirectionWall(from, p2.c > from.c ? 'east' : 'west');
        }
        // This check is simplified: we assume the global API check covers path validity
        return false; 
    }

     /** Checks if a specific wall direction between start and end cells is open. */
    _checkDirectionWall(start, direction) {
        const r = start.r;
        const c = start.c;
        if (direction === 'north') return !window.game.walls(r, c).n;
        if (direction === 'south') return !window.game.walls(r, c).s;
        if (direction === 'east') return !window.game.walls(r, c).e;
        if (direction === 'west') return !window.game.walls(r, c).w;
    }


    /** Gets delta changes for N, E, S, W */
    _getDelta(direction) {
        switch (direction) {
            case 'north': return [-1, 0];
            case 'east':  return [0, 1];
            case 'south': return [1, 0];
            case 'west':  return [0, -1];
        }
    }

     /** 
      * Handles arrival at exit. This MUST be called after a successful move(). 
      */
    checkExitArrival() {
        if (this.currentCell.r === window.game.exit.r && this.currentCell.c === window.game.exit.c) {
            if (this.finishTick === null) {
                this.finishTick = window.game.elapsed;
                console.log(`Bot ${this.id} arrived at exit at tick ${window.game.elapsed}.`);
            }
        }
    }
}

/** Maze Generation using Recursive Backtracker */
function generateMaze(seed) {
    const R = 20; // Grid height (at least 15)
    const C = 20; // Grid width (at least 15)

    // Initialize maze structure: map of Cell objects
    let mazeGrid = [];
    for (let r = 0; r < R; r++) {
        mazeGrid[r] = [];
        for (let c = 0; c < C; c++) {
            mazeGrid[r][c] = new Cell(r, c);
        }
    }

    const prng = new PRNG(seed * 13 + 1); // Mix seed for generation phase

    // Start at (0, 0)
    let stack = [{ r: 0, c: 0 }];
    mazeGrid[0][0].visited = true;

    while (stack.length > 0) {
        const current = stack[stack.length - 1];
        const neighbors = [];
        const directions = ['north', 'east', 'south', 'west'];

        // Find unvisited neighbors
        for (const dir of directions) {
            const [dr, dc] = [['north', [-1, 0]], ['east', [0, 1]], ['south', [1, 0]], ['west', [0, -1]]][directions.indexOf(dir)];
            const nr = current.r + dr;
            const nc = current.c + dc;

            if (nr >= 0 && nr < R && nc >= 0 && nc < C && !mazeGrid[nr][nc].visited) {
                neighbors.push({ cell: mazeGrid[nr][nc], direction: dir });
            }
        }

        // Shuffle neighbors deterministically using PRNG
        for (let i = 1; i < neighbors.length; i++) {
            const swapIndex = Math.floor(prng.next() * i);
            [neighbors[i], neighbors[swapIndex]] = [neighbors[swapIndex], neighbors[i]];
        }

        if (neighbors.length > 0) {
            const nextNeighborInfo = neighbors.pop(); // Pop the chosen neighbor
            const nextCell = nextNeighborInfo.cell;
            const direction = nextNeighborInfo.direction;

            // 1. Mark walls: Remove wall between current and next cell
            let oppositeDir, currentWallKey;
            if (direction === 'north') {
                mazeGrid[current.r][current.c].setWall('north', false);
                nextCell.setWall('south', false);
            } else if (direction === 'east') {
                mazeGrid[current.r][current.c].setWall('east', false);
                nextCell.setWall('west', false);
            } else if (direction === 'south') {
                mazeGrid[current.r][current.c].setWall('south', false);
                nextCell.setWall('north', false);
            } else if (direction === 'west') {
                mazeGrid[current.r][current.c].setWall('west', false);
                nextCell.setWall('east', false);
            }

            // 2. Update state
            nextCell.visited = true;
            stack.push(nextCell);

        } else {
            stack.pop(); // Backtrack
        }
    }

    return { grid: mazeGrid, R: R, C: C };
}


/** Rendering and Initialization Wrapper */
function setupGame() {
    const canvas = document.getElementById('maze');
    const ctx = canvas.getContext('2d');

    // Set initial game API state (needed before calling init)
    window.game.ctx = ctx;
    window.game.mazeCanvas = canvas;

    const seedInput = prompt("Enter a numeric seed for deterministic play:", Math.floor(Math.random() * 10000));
    const initialSeed = (seedInput === null || isNaN(parseInt(seedInput))) ? Math.floor(Math.random() * 10000) : parseInt(seedInput);

    // --- Core Initialization ---
    const { grid, R, C } = generateMaze(initialSeed);

    window.game.size = { rows: R, cols: C };
    window.game.maze = grid; // Attach the maze structure to the global game object for API access
    window.game.elapsed = 0;
    window.game.isFrozen = true;

    // Set mandatory starting points (e.g., top-left, bottom-right)
    window.game.spawn = { r: 0, c: 0 };
    window.game.exit = { r: R - 1, c: C - 1 };

    // --- Bot Setup ---
    const numBots = 24;
    window.game.bots = [];
    for (let i = 0; i < numBots; i++) {
        // Assign unique seed for bot preference spreading
        const botSeed = initialSeed * (i + 1) + 7; 
        const newBot = new Bot(i, botSeed);
        newBot.initialize(window.game.spawn.r, window.game.spawn.c);
        window.game.bots.push(newBot);
    }

    // --- UI Updates and Rendering ---
    document.getElementById('size_display').textContent = `${R}x${C}`;
    document.getElementById('spawn_display').textContent = `(${window.game.spawn.r}, ${window.game.spawn.c})`;
    document.getElementById('exit_display').textContent = `(${window.game.exit.r}, ${window.game.exit.c})`;

    // Call the game object's init method which uses the generated data
    window.game.init(initialSeed); 

    // Set up event listeners
    document.getElementById('reset').addEventListener('click', () => {
        if (confirm("Are you sure you want to reset?")) {
             // Pass current seed or re-prompt
            const newSeedInput = prompt("Enter a numeric seed for deterministic play:", initialSeed);
            const finalSeed = (newSeedInput === null || isNaN(parseInt(newSeedInput))) ? Math.floor(Math.random() * 10000) : parseInt(newSeedInput);
            window.game.reset(finalSeed);
        }
    });

    // Initial full render
    window.game.reset(initialSeed);
}


/** Renderer Handles drawing the maze, bots (with interpolation), and status UI. */
function _renderAll() {
    const ctx = window.game.ctx;
    const scale = 40 / 20; // Cell size: ~40px (adjusting for 20x20 grid)
    const R = window.game.size.rows;
    const C = window.game.size.cols;

    // Clear canvas
    ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);

    // Draw Maze and Walls
    drawMaze(ctx, scale, R, C);

    // Draw Bots (with interpolation)
    const bots = window.game.bots;
    for (let i = 0; i < bots.length; i++) {
        const bot = bots[i];
        if (bot.currentCell && bot.nextMove) {
