        } else if (bot.finishTick !== null) {
             // Draw finished bots as static marker
             drawFinishedBot(ctx, scale, bot);
        }
    }

    // Update UI Status
    const completedCount = bots.filter(b => b.finishTick !== null).length;
    document.getElementById('completed').textContent = `${completedCount}`;
}

/** Draws the static maze structure (walls and passages) */
function drawMaze(ctx, scale, R, C) {
    // Walls are drawn first: background grid lines
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            const cell = window.game.maze[r][c];

            ctx.strokeStyle = '#444'; // Wall color

            // Draw North wall segment (top edge)
            ctx.beginPath();
            ctx.moveTo(c * scale, r * scale);
            ctx.lineTo((c + 1) * scale, r * scale);
            if (!cell.walls.north && r > 0) { // If passage exists North from here
                // The wall is already removed by setting cell.setWall(false), so we just draw the line if it's not a barrier
                 ctx.strokeStyle = '#444'; // Draw invisible passage edge
            } else if (r < R - 1 && window.game.maze[r+1][c].walls.north) {
                // This is tricky due to rendering edges vs cell walls. Let's simplify: draw full grid lines and then erase passages.
                 ctx.lineWidth = 2; // For drawing visible structure
            } else if (window.game.maze[r+1][c].walls.north === false) {
                // If the wall is removed, it means passage exists. We skip drawing a physical divider here to look like an open corridor.
            }
             ctx.stroke();
        }
    }

    // Draw floor/passages (A solid background color helps visualization)
    ctx.fillStyle = '#f9f9f9';
    ctx.fillRect(0, 0, C * scale, R * scale);


    // Redraw walls explicitly for visual clarity:
    ctx.strokeStyle = '#333'; // Darker wall lines
    ctx.lineWidth = 2;

