                ctx.beginPath();
                ctx.moveTo(x, y);
                ctx.lineTo(x + scale, y); // Horizontal line at top
                ctx.stroke();
            }

            if (cell.walls.east) {
                 // East wall is drawn by the current cell's right boundary
            }
             if (cell.walls.south) {
                ctx.beginPath();
                ctx.moveTo(x, y + scale);
                ctx.lineTo(x + scale, y + scale); // Vertical line at bottom
                ctx.stroke();
            }

            // Handle internal dividers manually for clean rendering
            if (c < C - 1) {
                 const nextCell = window.game.maze[r][c+1];
                 if (cell.walls.east) { // If current cell has an east wall, it means passage is blocked from the left side.
                     ctx.beginPath();
                     ctx.moveTo((c + 1) * scale, y);
                     ctx.lineTo((c + 1) * scale, y + scale);
                     ctx.stroke(); // Vertical divider
                 }
            }
             if (r < R - 1) {
                const nextCell = window.game.maze[r+1][c];
                if (cell.walls.south) {
                    // Horizontal divider drawn by the current cell's bottom wall check
                }
            }

        }
    }

     // Simple approach: Draw a solid grid and then use semi-transparency/overlap to indicate passages
    ctx.globalAlpha = 0.9;
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            const x = c * scale;
            const y = r * scale;

            // Draw vertical line segment at the right boundary of the cell, if wall exists
            if (c < C - 1) {
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 2;
                if (window.game.maze[r][c].walls.east || window.game.maze[r][c+1].walls.west) {
                     ctx.beginPath();
                     ctx.moveTo((c + 1) * scale, y);
                     ctx.lineTo((c + 1) * scale, y + scale);
                     ctx.stroke();
                } else {
                    // Passage open: Draw a fainter line or nothing to indicate openness
                     ctx.beginPath();
                     ctx.moveTo((c + 1) * scale - 2, y);
                     ctx.lineTo((c + 1) * scale - 2, y + scale);
                     ctx.strokeStyle = '#777'; // Faint line for passage edge
                     ctx.stroke();
                }
            }

             // Draw horizontal line segment at the bottom boundary of the cell, if wall exists
            if (r < R - 1) {
                 ctx.beginPath();
                 ctx.moveTo(x, (r + 1) * scale);
                 ctx.lineTo(x + scale, (r + 1) * scale);
                 ctx.strokeStyle = '#333';
                 ctx.lineWidth = 2;

                 if (window.game.maze[r][c].walls.south || window.game.maze[r+1][c].walls.north) {
                    // Passage open: Draw fainter line
                      ctx.strokeStyle = '#777';
                     ctx.stroke(); 
                 } else {
                      // Wall blocked: Draw solid line
                      ctx.strokeStyle = '#333';
                      ctx.lineWidth = 2;
                      ctx.stroke();
                 }
            }
        }
    }

    // Re-apply global alpha for the drawing bots layer
    ctx.globalAlpha = 1.0;
}


/** Draws a bot smoothly interpolated between current and next position (moving). */
function drawBot(ctx, scale, bot) {
    const r = bot.currentCell.r;
    const c = bot.currentCell.c;

    // Interpolation: Calculate the fraction of distance traveled towards nextMove
    let progressX = 0;
    let progressY = 0;
    let totalSteps = Math.max(1, Math.abs(window.game.elapsed % (20/30)) / 2); // Simple rate control based on tick

    // Since we are rendering synchronously after a tick update, the bot's position should be 
    // exactly at 'nextMove' if movement was successful in that tick cycle.
    // We assume for simplicity that `move()` places the agent *exactly* into the next cell coordinates upon success.
    const x = (c + (window.game.elapsed % 1) * 0.5) * scale; // Simplified interpolation placeholder
    const y = (r + (window.game.elapsed % 1) * 0.5) * scale;

